// Text helpers. All text in a video is typeset by the browser from the input
// strings: nothing is ever generated by an image model, so names and quotes
// come out spelled exactly as given.

/**
 * Split text into words, marking *emphasised* spans.
 *   parseEmphasis('Build *daily habits*, not goals')
 *   → [{text:'Build',em:false},{text:'daily',em:true},{text:'habits,',em:true},...]
 * A literal asterisk can be written as \*.
 */
export function parseEmphasis(text) {
  const words = [];
  let em = false;
  let cur = '';
  let curEm = false;
  const push = () => {
    if (cur) words.push({ text: cur, em: curEm });
    cur = '';
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '\\' && text[i + 1] === '*') {
      if (!cur) curEm = em;
      cur += '*';
      i++;
    } else if (c === '*') {
      if (cur && em) {
        // closing marker glued to the word: the whole word is emphasised
        curEm = true;
      }
      em = !em;
      if (!cur) curEm = em;
    } else if (/\s/.test(c)) {
      push();
      curEm = em;
    } else {
      if (!cur) curEm = em;
      cur += c;
    }
  }
  push();
  return words;
}

/** Strip emphasis markers: '*a* b' → 'a b'. */
export const plainText = (text) => parseEmphasis(text).map((w) => w.text).join(' ');

/**
 * Binary-search the largest font size (px) at which `node`'s content fits
 * inside maxWidth × maxHeight. The node must be in the document. Returns the
 * chosen size and leaves it applied.
 */
export function fitText(node, { maxWidth, maxHeight = Infinity, min = 12, max = 400, precision = 0.5 } = {}) {
  const fits = (size) => {
    node.style.fontSize = `${size}px`;
    const w = node.scrollWidth;
    const h = node.scrollHeight;
    return w <= maxWidth + 0.5 && h <= maxHeight + 0.5;
  };
  if (!fits(min)) {
    node.style.fontSize = `${min}px`;
    return min;
  }
  let lo = min;
  let hi = max;
  while (hi - lo > precision) {
    const mid = (lo + hi) / 2;
    if (fits(mid)) lo = mid;
    else hi = mid;
  }
  node.style.fontSize = `${lo}px`;
  return lo;
}

/**
 * Group laid-out inline elements into visual lines by their top offset.
 * Returns [[el, el], [el], ...] in reading order.
 */
export function groupLines(elements) {
  const lines = [];
  let lastTop = null;
  for (const e of elements) {
    const top = Math.round(e.offsetTop);
    if (lastTop === null || Math.abs(top - lastTop) > 2) {
      lines.push([]);
      lastTop = top;
    }
    lines[lines.length - 1].push(e);
  }
  return lines;
}

/** Collect every string inside a JSON-ish value (for font preloading). */
export function collectText(value, out = []) {
  if (typeof value === 'string') out.push(value);
  else if (Array.isArray(value)) value.forEach((v) => collectText(v, out));
  else if (value && typeof value === 'object') Object.values(value).forEach((v) => collectText(v, out));
  return out;
}

/** Zero-pad a number: pad(7, 3) → '007'. */
export const pad = (n, width = 2) => String(n).padStart(width, '0');
